 '\n'
 '            textureObject->setAllocated(true);\n'
 '#if !defined(OSG_GL_FIXED_FUNCTION_AVAILABLE)\n'
 '            /* FlightGear GLES port: uploads driven by the IncrementalCompileOperation\n'
